uv run python - <<'PY'
import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)
folds = np.arange(len(y)) % 5
rng = np.random.default_rng(0)

class Node:
    __slots__ = ('pred','f','t','l','r')
    def __init__(self,pred,f=None,t=None,l=None,r=None):
        self.pred=pred; self.f=f; self.t=t; self.l=l; self.r=r

def gini(count1, n):
    if n == 0:
        return 0.0
    p = count1 / n
    return 1.0 - p*p - (1-p)*(1-p)

def build_tree(X, y, depth, max_depth, min_leaf, mtry, rng):
    n = len(y)
    pred = int(y.mean() >= 0.5)
    if depth >= max_depth or n <= 2*min_leaf or y.min() == y.max():
        return Node(pred)
    features = rng.choice(X.shape[1], size=min(mtry, X.shape[1]), replace=False)
    best = None
    parent_imp = gini(y.sum(), n)
    for f in features:
        col = X[:, f]
        vals = np.unique(col)
        if len(vals) < 2:
            continue
        qs = np.quantile(vals, [0.2,0.4,0.6,0.8])
        for t in np.unique(qs):
            left = col <= t
            nl = int(left.sum())
            nr = n - nl
            if nl < min_leaf or nr < min_leaf:
                continue
            yl = y[left]
            yr = y[~left]
            imp = (nl/n)*gini(yl.sum(), nl) + (nr/n)*gini(yr.sum(), nr)
            gain = parent_imp - imp
            if best is None or gain > best[0]:
                best = (gain, f, float(t), left)
    if best is None or best[0] <= 0:
        return Node(pred)
    _, f, t, left = best
    return Node(pred, f, t,
        build_tree(X[left], y[left], depth+1, max_depth, min_leaf, mtry, rng),
        build_tree(X[~left], y[~left], depth+1, max_depth, min_leaf, mtry, rng))

def predict_tree(node, X):
    out = np.empty(len(X), dtype=int)
    for i, row in enumerate(X):
        cur = node
        while cur.f is not None:
            cur = cur.l if row[cur.f] <= cur.t else cur.r
        out[i] = cur.pred
    return out

def forest_predict(Xtr, ytr, Xva, n_trees=31, max_depth=5, min_leaf=20, mtry=10):
    preds = np.zeros(len(Xva), dtype=float)
    n = len(ytr)
    for i in range(n_trees):
        idx = rng.integers(0, n, size=n)
        tree = build_tree(Xtr[idx], ytr[idx], 0, max_depth, min_leaf, mtry, rng)
        preds += predict_tree(tree, Xva)
    return (preds >= n_trees/2).astype(int)

scores=[]
for f in range(5):
    tr = folds != f
    va = ~tr
    pred = forest_predict(X[tr], y[tr], X[va])
    scores.append(float((pred == y[va]).mean()))
print('rf_like', np.mean(scores), scores)
